Uses the photo’s EXIF date, falling back to file date. Install Pillow first: pip install pillow

from pathlib import Path
from datetime import datetime
from PIL import Image

folder = Path(r"/path/to/photos")

def photo_date(path):
    try:
        with Image.open(path) as img:
            exif = img.getexif()
            raw = exif.get(36867) or exif.get(36868) or exif.get(306)
            if raw:
                return datetime.strptime(str(raw), "%Y:%m:%d %H:%M:%S")
    except Exception:
        pass
    return datetime.fromtimestamp(path.stat().st_mtime)

for path in sorted(folder.iterdir()):
    if not path.is_file() or path.name.startswith("."):
        continue
    stamp = photo_date(path).strftime("%Y-%m-%d_%H-%M-%S")
    target = path.with_name(stamp + path.suffix.lower())
    n = 1
    while target.exists() and target != path:
        target = path.with_name(f"{stamp}_{n}{path.suffix.lower()}")
        n += 1
    if target != path:
        path.rename(target)

