Yep — this uses the photo’s EXIF date when it has one, and falls back to the file’s modified date. `pip install pillow`, then set `FOLDER`:

```python
from pathlib import Path
from datetime import datetime
from PIL import Image
from PIL.ExifTags import TAGS

FOLDER = Path("/path/to/your/photos")
EXTENSIONS = {".jpg", ".jpeg", ".png", ".heic"}

for path in list(FOLDER.iterdir()):
    if not path.is_file() or path.suffix.lower() not in EXTENSIONS:
        continue

    date = None
    try:
        exif = Image.open(path).getexif()
        tags = {TAGS.get(k, k): v for k, v in exif.items()}
        raw = tags.get("DateTimeOriginal") or tags.get("DateTime")
        if raw:
            date = datetime.strptime(str(raw), "%Y:%m:%d %H:%M:%S")
    except Exception:
        pass

    if date is None:
        date = datetime.fromtimestamp(path.stat().st_mtime)

    base = date.strftime("%Y-%m-%d_%H-%M-%S")
    target = path.with_name(base + path.suffix.lower())
    n = 1
    while target.exists() and target != path:
        target = path.with_name(f"{base}_{n}{path.suffix.lower()}")
        n += 1

    if target != path:
        path.rename(target)
```

